# Patch: write minimal_report.json with plain Python types

import json
from pathlib import Path

root = Path("/mnt/data/clock_paper_run/session2")

def to_bool(x):  # convert numpy.bool_ to Python bool
    return bool(x)

report_clean = {
    "session_seed": int(seed),
    "f_hz": float(f_hz),
    "block_seconds": int(block_seconds),
    "window_len_s": int(win_len),
    "blind_map_path": str(root / "blind_map.json"),
    "blinded_summary_path": str(root / "blinded_block_summary.csv"),
    "unblinded_block_stats_path": str(root / "unblinded_block_stats.csv"),
    "contrasts": {
        "C1_X_minus_Sham": {"mean_diff_frac": float(c1_stat), "p_value_one_sided": float(c1_p)},
        "C2_X_minus_Y": {"mean_diff_frac": float(c2_stat), "p_value_one_sided": float(c2_p)},
        "C3_avgXY_minus_Control": {"mean_diff_frac": float(c3_stat), "p_value_two_sided": float(c3_p)}
    },
    "decision": {
        "SOI_threshold_abs_delta": 3e-12,
        "block_estimates_frac": {k: float(v) for k, v in detrended_block.items()},
        "criteria": {
            "abs_X_ge_SOI": to_bool(abs(detrended_block["B_ActivX"]) >= 3e-12),
            "abs_Y_ge_SOI": to_bool(abs(detrended_block["D_ActivY"]) >= 3e-12),
            "sign_flip": to_bool(np.sign(detrended_block["B_ActivX"]) == -np.sign(detrended_block["D_ActivY"])),
            "sham_near_zero": to_bool(abs(detrended_block["C_ShamX"]) <= 1e-12),
            "pvals": {
                "C1<0.01": to_bool(c1_p < 0.01),
                "C2<0.01": to_bool(c2_p < 0.01),
                "C3_ns": to_bool(c3_p > 0.05)
            }
        }
    }
}

with open(root / "minimal_report.json", "w") as f:
    json.dump(report_clean, f, indent=2)

print({
    "minimal_report_json": str(root / "minimal_report.json"),
    "c1_p_one_sided": float(c1_p),
    "c2_p_one_sided": float(c2_p),
    "c3_p_two_sided": float(c3_p)
})

