# Re-run the tail of Session 5 to write outputs (no display function used)
import numpy as np
import pandas as pd
import json
from pathlib import Path

root = Path("/mnt/data/clock_paper_run/session5_very_low_noise")

# If previous variables exist from Session 5 cell, reuse; else recompute quickly
try:
    blocks
    detrended_block
    c1_p; c2_p; c3_p; c1_stat; c2_stat; c3_stat
except NameError:
    raise RuntimeError("Prereq variables missing; please re-run Session 5 setup cell.")

pd.DataFrame([
    {"block": k, "delta_block_frac_detrended": float(detrended_block[k])}
    for k in blocks
]).to_csv(root / "unblinded_block_stats.csv", index=False)

Path(root / "minimal_report.json").write_text(json.dumps({
    "session_seed": int(seed),
    "contrasts": {
        "C1_X_minus_Sham": {"mean_diff_frac": float(c1_stat), "p_value_one_sided": float(c1_p)},
        "C2_X_minus_Y":    {"mean_diff_frac": float(c2_stat), "p_value_one_sided": float(c2_p)},
        "C3_avgXY_minus_Control": {"mean_diff_frac": float(c3_stat), "p_value_two_sided": float(c3_p)}
    },
    "block_estimates_frac_detrended": {k: float(v) for k, v in detrended_block.items()}
}, indent=2))

print("Done. Files written:", {
    "unblinded_csv": str(root / "unblinded_block_stats.csv"),
    "report": str(root / "minimal_report.json")
})

